/**
 * Abrir la factura del plan en una nueva pestaña del navegador.
 *
 * @param {number} factura_id Id de la factura.
 * @returns {void}
 * @author Fahibram Cárcamo
 * @author Andres Morales
 */
async function abrirFacturaPlan(factura_id){
    if (factura_id) {
        await $.ajax({
            type: 'GET',
            url: `archivos-abrir/${factura_id}`,
            xhrFields: {responseType: 'blob'},
        })
            .then(respuesta => {
                let ruta_factura = window.URL.createObjectURL(respuesta);
                window.open(ruta_factura, '_blank');
            })
            .catch((error) => {
                mostrarToast('danger', 'Ocurrió un error en la solicitud');
            });
    } else {
        mostrarToast('danger', 'No se encontró la factura');
    }
}

/**
 *  Generar el contenido del tooltip para las pruebas asignadas a un plan.
 *
 * @param {array} pruebas Array de objetos de pruebas asignadas.
 * @returns {string} Contenido HTML del tooltip.
 * @author Esperanza Olivo
 */
function generarTooltipPruebasPlan(pruebas, plan_nombre='') {
    if (!pruebas || pruebas.length === 0) return 'Sin pruebas asignadas';
    let lineas = [];

     if (plan_nombre) {
        lineas.push(`${plan_nombre.replace(/&/g, '&amp;')}`);
    }

    pruebas.forEach(prueba => {
        let nombre = prueba.nombre?.replace(/&/g, '&amp;') ?? 'Prueba';
        let ruta = slugify(prueba.nombre ?? '');
        lineas.push(`<img src='/imagenes/logos/pruebas/${ruta}.png' width='14' height='14'>${nombre}`);
    });

    return lineas.join('<br>');
}

/**
 *  Generar el contenido del tooltip para los consumos de las pruebas asignadas a un plan, agrupados por prueba.
 *
 * @param {array} consumos Lista de objetos de consumos del plan.
 * @param {number} total_unidades Total de unidades consumidas del plan.
 * @param {array} pruebas Lista de objetos de pruebas asignadas al plan.
 * @returns {string} Contenido HTML del tooltip.
 * @author Esperanza Olivo
 */
function generarTooltipConsumosPruebas(consumos, total_unidades, pruebas) {
    if (!pruebas || pruebas.length === 0) {
        return 'Sin datos de consumo';
    }

    let consumos_por_prueba = [];
    pruebas.forEach(prueba => {
        consumos_por_prueba.push({ nombre: prueba.nombre, cantidad: 0 });
    });

    if (consumos && consumos.length > 0) {
        consumos.forEach(consumo => {
            if (consumo.agenda?.prueba?.nombre) {
                let nombre = consumo.agenda.prueba.nombre;
                let prueba = consumos_por_prueba.find(prueba => prueba.nombre === nombre);
                if (prueba) {
                    prueba.cantidad++;
                }
            }
        });
    }

    let lineas = [`Unidades consumidas: ${total_unidades ?? 0}`];
    consumos_por_prueba.forEach(prueba => {
        let nombre = prueba.nombre.replace(/&/g, '&amp;');
        let ruta = slugify(prueba.nombre);
        lineas.push(`<img src='/imagenes/logos/pruebas/${ruta}.png' width='14' height='14'> ${nombre}: ${prueba.cantidad}`);
    });

    return lineas.join('<br>');
}

